import{_ as s,o as r,c as t,ah as i}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Frais et tarification","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/frais-tarification.md","filePath":"src/guide/admin/frais-tarification.md"}'),a={name:"guide/admin/frais-tarification.md"};function n(l,e,o,u,c,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="frais-et-tarification" tabindex="-1">Frais et tarification <a class="header-anchor" href="#frais-et-tarification" aria-label="Permalink to &quot;Frais et tarification&quot;">​</a></h1><p>Cette section couvre la définition des montants dus par les familles (grilles de frais) et les remises que vous pouvez accorder au cas par cas. L&#39;encaissement des paiements eux-mêmes est le travail quotidien de la caisse — vous n&#39;intervenez ici que sur la tarification et les remises.</p><h2 id="grilles-de-frais" tabindex="-1">Grilles de frais <a class="header-anchor" href="#grilles-de-frais" aria-label="Permalink to &quot;Grilles de frais&quot;">​</a></h2><p><strong>Paramétrage scolaire → Grilles de frais</strong> définit la liste des frais dus par les élèves d&#39;un site, pour une année scolaire. Une grille s&#39;applique à l&#39;un de ces trois choix (<strong>S&#39;applique à</strong>) :</p><ul><li><strong>Tout le département</strong> : toutes les classes du département sur ce site ;</li><li><strong>Un niveau</strong> : toutes les classes de ce niveau (par exemple la 6e) ;</li><li><strong>Une classe</strong> : une seule classe (par exemple la 6e A).</li></ul><p>La grille la plus précise l&#39;emporte : un élève est facturé selon la grille de sa classe, à défaut celle de son niveau, à défaut celle de son département. Vous pouvez donc garder une grille de département pour le cas général et n&#39;ajouter une grille de niveau ou de classe que là où les montants diffèrent. Un élève sans aucune grille correspondante n&#39;a aucun montant calculé.</p><p>Pour créer une grille de frais :</p><ol><li>Cliquez sur <strong>Nouvelle grille de frais</strong>.</li><li>Choisissez le <strong>Site</strong>, le <strong>Département</strong> et l&#39;<strong>Année scolaire</strong>.</li><li>Dans <strong>S&#39;applique à</strong>, choisissez tout le département, un niveau ou une classe, puis le niveau ou la classe concernés.</li><li>Ajoutez un ou plusieurs articles de frais avec <strong>Ajouter un article</strong>, en renseignant pour chacun les champs ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Libellé</td><td>ex. « Frais de scolarité », « Cantine »</td></tr><tr><td>Montant</td><td>—</td></tr><tr><td>Optionnel</td><td>cochez pour un service au choix (cantine, transport…) : le parent le coche depuis son espace, ou la caisse depuis le dossier de l&#39;élève</td></tr><tr><td>Catégorie</td><td>Générale, Cantine ou Transport</td></tr></tbody></table><p>Modifier une grille existante permet d&#39;ajouter, changer ou retirer des articles de frais. Une grille déjà utilisée (un paiement ou un service choisi) ne peut plus changer de site, de département, d&#39;année ni de cible : créez-en une nouvelle. Supprimer une grille supprime aussi définitivement tous ses articles.</p><div class="info custom-block"><p class="custom-block-title">Services optionnels</p><p>Quand une grille de niveau ou de classe prend le relais d&#39;une grille de département, les services optionnels déjà choisis par les élèves concernés passent sur la nouvelle grille s&#39;il y figure un service équivalent (même catégorie et même libellé). Un service absent de la nouvelle grille est retiré.</p></div><p>À la préparation d&#39;une nouvelle année, les grilles de niveau et de classe sont copiées comme les autres ; une grille de classe va à la classe du même nom sur le même site, et n&#39;est pas copiée si cette classe n&#39;existe pas encore.</p><h2 id="remises" tabindex="-1">Remises <a class="header-anchor" href="#remises" aria-label="Permalink to &quot;Remises&quot;">​</a></h2><p>Les remises se gèrent non pas sur la grille de frais elle-même, mais sur la facturation d&#39;un élève précis : <strong>Finances → Facturation</strong>, recherchez l&#39;élève, cliquez sur <strong>Voir</strong> pour ouvrir son dossier de facturation.</p><p>Sur cet écran, vous seul (en tant qu&#39;administrateur — la caisse ne peut qu&#39;encaisser des paiements) pouvez accorder ou retirer une remise :</p><p>Pour accorder une remise :</p><ol><li>Dans la section « Remises », renseignez le <strong>Libellé</strong> de la remise.</li><li>Choisissez le <strong>Type</strong> : Montant fixe ou Pourcentage.</li><li>Renseignez la <strong>Valeur</strong> correspondante et, facultativement, un <strong>Motif</strong>.</li><li>Cliquez sur <strong>Accorder la remise</strong>.</li></ol><p>Chaque remise accordée s&#39;affiche avec le nom de l&#39;administrateur qui l&#39;a créée. Le bouton <strong>Retirer cette remise</strong> (dans la liste des remises) la supprime définitivement — le <strong>Solde</strong> de l&#39;élève est recalculé immédiatement.</p>',18)])])}const g=s(a,[["render",n]]);export{m as __pageData,g as default};
